2. Parse each URL with urllib.parse.urlparse to obtain its network location (netloc).
3. Normalize each domain by stripping any port numbers and converting it to lowercase.
4. Deduplicate the list of domains to avoid redundant API calls.
5. For each domain, build the IP API request URL using the provided API_KEY and perform an HTTP GET request.
6. If the request succeeds and returns valid JSON, store the parsed JSON as the value for that domain; if it fails due to network or parsing issues, store None.
7. Return the dictionary that maps each domain to its corresponding geolocation data or None.

### code
```python
import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    if not isinstance(myString, str):
        raise ValueError("myString must be a string")
    if not API_KEY:
        raise ValueError("API_KEY must be provided")

    url_pattern = r'https?://[^\s"\']+'
    urls = re.findall(url_pattern, myString)

    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        netloc = parsed.netloc
        if not netloc:
            continue
        if '@' in netloc:
            netloc = netloc.split('@', 1)[1]
        if ':' in netloc:
            netloc = netloc.split(':', 1)[0]
        netloc = netloc.strip().lower()
        if netloc:
            domains.add(netloc)

    result = {}
    for domain in domains:
        api_url = f"http://ip-api.com/json/{domain}"
        params = {"key": API_KEY}
        try:
            response = requests.get(api_url, params=params, timeout=10)
            response.raise_for_status()
            try:
                data = response.json()
            except json.JSONDecodeError:
                data = None
            result[domain] = data
        except requests.RequestException:
            result[domain] = None

    return result
