4. Convert the JSON data into a pandas DataFrame and verify that it contains at least one numerical column; raise an Exception if not.
5. Compute the correlation matrix of the numerical columns.
6. Plot a heatmap of the correlation matrix using seaborn, display it, and return a tuple containing the DataFrame and the matplotlib Axes object.

### code
```python
import requests
import json
import pandas as pd
import seaborn as sns
# Constants
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url.strip():
        raise Exception("Invalid URL")
    if parameters is None or not isinstance(parameters, dict):
        raise Exception("Invalid parameters")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
    except Exception as e:
        raise Exception(f"Error accessing URL: {e}")
    try:
        data = response.json()
    except Exception as e:
        raise Exception(f"Invalid JSON data: {e}")
    if not data:
        raise Exception("Empty data received from API")
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Invalid data format for DataFrame: {e}")
    if df.empty:
        raise Exception("DataFrame is empty")
    numeric_df = df.select_dtypes(include="number")
    if numeric_df.empty:
        raise Exception("No numerical data available for correlation")
    corr = numeric_df.corr()
    if corr.empty:
        raise Exception("Correlation matrix is empty")
    ax = sns.heatmap(corr, annot=False, cmap="viridis")
    ax.figure.canvas.draw()
    return df, ax
